import { useState } from 'react'
import { Icon } from '@/design-system/Icon'
import {
  Card,
  EmptyState,
  Field,
  PARTNER_VISIBILITY_OPTIONS,
  Sheet,
  VisibilityBadge,
} from '@/components/ui'
import { useSession } from '@/app/session'
import { useOwned } from '@/db/hooks'
import { db, newEnvelope, patch, setVisibility, softDelete } from '@/db/db'
import { useI18n } from '@/i18n'
import { formatRupiah, whenLabel } from '@/i18n/format'
import type { Visibility } from '@/types/domain'
import {
  URGENCIES,
  WISHES,
  groupWishes,
  isReservation,
  normalizeLink,
  parsePrice,
  priceSummary,
  reservationOf,
  safeLink,
  type Reservation,
  type Urgency,
  type Wish,
  type WishRecord,
  type WishScope,
} from './wishlist'

/**
 * Wishlist — three lists on one screen.
 *
 * The feature only works if a gift can stay a gift. Everything a giver marks
 * (reserved, already given) is written as their own `private` record, so the
 * owner cannot read it back — see the note at the top of `wishlist.ts`. Nothing
 * on this screen tells anyone who gave more; there is no count per person.
 */

const SCOPES: readonly WishScope[] = ['sendiri', 'bareng']

const URGENCY_CHIP: Record<Urgency, string> = {
  lagi_butuh: 'chip chip--yellow',
  lagi_pengin: 'chip chip--blue',
  kapan_kapan: 'chip',
}

interface Draft {
  id?: string
  title: string
  note: string
  price: string
  link: string
  urgency: Urgency
  scope: WishScope
  visibility: Visibility
}

const emptyDraft = (scope: WishScope): Draft => ({
  title: '',
  note: '',
  price: '',
  link: '',
  urgency: 'lagi_pengin',
  // A wishlist nobody can read is pointless, so a new wish starts shared. The
  // owner still gets the picker below and can pull it back to private.
  scope,
  visibility: 'shared',
})

export default function Wishlist() {
  const { t } = useI18n()
  const { profile, profiles } = useSession()
  const me = profile?.id
  const rows = useOwned<WishRecord>(WISHES, me)
  const [draft, setDraft] = useState<Draft | null>(null)
  const [linkError, setLinkError] = useState(false)

  if (!profile || !me) return null

  const partner = profiles.find((p) => p.id !== me) ?? null
  const all = rows ?? []
  // Only ever *my own* reservations survive the read gate — the partner's are
  // private to them, which is exactly why the surprise works both ways.
  const reservations = all.filter(isReservation)
  const { mine, partner: theirs, together } = groupWishes(all, me)

  async function save() {
    if (!draft || !me) return
    const title = draft.title.trim()
    if (!title) return
    const link = normalizeLink(draft.link)
    if (draft.link.trim() && !link) {
      setLinkError(true)
      return
    }
    const body = {
      kind: 'wish' as const,
      title,
      urgency: draft.urgency,
      scope: draft.scope,
      note: draft.note.trim() || undefined,
      priceEstimate: parsePrice(draft.price),
      link,
    }

    if (draft.id) {
      await patch(WISHES, draft.id, body)
      const existing = all.find((r) => r.id === draft.id)
      if (existing && existing.ownerProfileId === me && draft.scope === 'sendiri' && existing.visibility !== draft.visibility) {
        await setVisibility(WISHES, draft.id, me, draft.visibility)
      }
    } else {
      const joint = draft.scope === 'bareng'
      await db.table(WISHES).add({
        ...newEnvelope(me, 'C3_relationship', {
          visibility: joint ? 'both_partners' : draft.visibility,
          coOwnerProfileIds: joint && partner ? [partner.id] : [],
        }),
        ...body,
      } as never)
    }
    setDraft(null)
    setLinkError(false)
  }

  async function reserve(w: Wish) {
    if (!me) return
    // Default C3 visibility is 'private'; that default IS the guarantee here, so
    // this create deliberately passes no visibility override.
    await db.table(WISHES).add({
      ...newEnvelope(me, 'C3_relationship'),
      kind: 'reservation',
      wishId: w.id,
      status: 'diambil',
    } as never)
  }

  function openEdit(w: Wish) {
    setDraft({
      id: w.id,
      title: w.title,
      note: w.note ?? '',
      price: w.priceEstimate ? String(w.priceEstimate) : '',
      link: w.link ?? '',
      urgency: w.urgency,
      scope: w.scope,
      visibility: w.visibility,
    })
  }

  const editingJoint = draft?.scope === 'bareng'

  return (
    <div className="stack">
      <h1>{t('wishlist.title')}</h1>
      <p className="card__hint">{t('wishlist.intro')}</p>

      <WishSection
        title={t('wishlist.mine')}
        hint={t('wishlist.mineHint')}
        wishes={mine}
        emptyTitle={t('wishlist.empty')}
        emptyHint={t('wishlist.emptyHint')}
        onAdd={() => setDraft(emptyDraft('sendiri'))}
        renderRow={(w) => (
          <OwnerRow key={w.id} wish={w} me={me} onEdit={() => openEdit(w)} showVisibility />
        )}
      />

      {partner ? (
        <WishSection
          title={t('wishlist.partner', { name: partner.displayName })}
          hint={t('wishlist.partnerHint', { name: partner.displayName })}
          wishes={theirs}
          emptyTitle={t('wishlist.emptyPartner', { name: partner.displayName })}
          emptyHint={t('wishlist.emptyPartnerHint')}
          banner={t('wishlist.secretBanner', { name: partner.displayName })}
          renderRow={(w) => (
            <GiverRow
              key={w.id}
              wish={w}
              me={me}
              reservation={reservationOf(reservations, w.id)}
              onReserve={() => reserve(w)}
            />
          )}
        />
      ) : (
        <Card>
          {/* No partner profile means no partner list — an "add a wish for them"
              button here would do nothing, so it is not drawn. */}
          <EmptyState
            icon="unpair"
            title={t('wishlist.noPartner')}
            hint={t('wishlist.noPartnerHint')}
          />
        </Card>
      )}

      <WishSection
        title={t('wishlist.together')}
        hint={t('wishlist.togetherHint')}
        wishes={together}
        emptyTitle={t('wishlist.emptyTogether')}
        emptyHint={t('wishlist.emptyTogetherHint')}
        onAdd={() => setDraft(emptyDraft('bareng'))}
        renderRow={(w) => <OwnerRow key={w.id} wish={w} me={me} onEdit={() => openEdit(w)} />}
      />

      <Sheet
        open={draft !== null}
        onClose={() => {
          setDraft(null)
          setLinkError(false)
        }}
        title={draft?.id ? t('wishlist.editTitle') : t('wishlist.newTitle')}
      >
        {draft && (
          <div className="stack">
            <Field label={t('wishlist.fTitle')}>
              {(p) => (
                <input
                  {...p}
                  type="text"
                  value={draft.title}
                  placeholder={t('wishlist.fTitlePh')}
                  onChange={(e) => setDraft({ ...draft, title: e.target.value })}
                />
              )}
            </Field>

            <ChoiceRow
              legend={t('wishlist.fUrgency')}
              options={URGENCIES}
              value={draft.urgency}
              label={(u) => t(`wishlist.u.${u}` as const)}
              onChange={(u) => setDraft({ ...draft, urgency: u })}
            />

            <Field label={t('wishlist.fNote')} hint={t('common.optional')}>
              {(p) => (
                <textarea
                  {...p}
                  rows={2}
                  value={draft.note}
                  placeholder={t('wishlist.fNotePh')}
                  onChange={(e) => setDraft({ ...draft, note: e.target.value })}
                />
              )}
            </Field>

            <Field label={t('wishlist.fPrice')} hint={t('wishlist.fPriceHint')}>
              {(p) => (
                <input
                  {...p}
                  type="text"
                  inputMode="numeric"
                  value={draft.price}
                  onChange={(e) => setDraft({ ...draft, price: e.target.value })}
                />
              )}
            </Field>

            <Field
              label={t('wishlist.fLink')}
              hint={t('wishlist.fLinkHint')}
              error={linkError ? t('wishlist.linkInvalid') : undefined}
            >
              {(p) => (
                <input
                  {...p}
                  type="url"
                  value={draft.link}
                  onChange={(e) => {
                    setLinkError(false)
                    setDraft({ ...draft, link: e.target.value })
                  }}
                />
              )}
            </Field>

            {/* Moving a wish between lists after the fact would change who owns
                it and who already reserved it, so the list is picked once. */}
            {!draft.id && (
              <ChoiceRow
                legend={t('wishlist.fScope')}
                options={SCOPES}
                value={draft.scope}
                label={(s) => t(`wishlist.scope.${s}` as const)}
                onChange={(s) => setDraft({ ...draft, scope: s })}
              />
            )}

            {editingJoint ? (
              <p className="card__hint">{t('wishlist.jointNote')}</p>
            ) : (
              <Field label={t('common.whoCanSee')} hint={t('wishlist.visHint')}>
                {(p) => (
                  <select
                    {...p}
                    value={draft.visibility}
                    onChange={(e) =>
                      setDraft({ ...draft, visibility: e.target.value as Visibility })
                    }
                  >
                    {PARTNER_VISIBILITY_OPTIONS.map((v) => (
                      <option key={v} value={v}>
                        {t(`vis.${v}` as const)}
                      </option>
                    ))}
                  </select>
                )}
              </Field>
            )}

            <button className="btn btn--block" onClick={save} disabled={!draft.title.trim()}>
              {t('common.save')}
            </button>
          </div>
        )}
      </Sheet>
    </div>
  )
}

/**
 * Single-select as a row of buttons. A `<fieldset>` rather than `Field`, because
 * `Field`'s `<label for>` needs one control to point at and a button group has
 * none — a dangling `for` is worse than no label.
 */
function ChoiceRow<T extends string>({
  legend,
  options,
  value,
  label,
  onChange,
}: {
  legend: string
  options: readonly T[]
  value: T
  label: (option: T) => string
  onChange: (option: T) => void
}) {
  return (
    <fieldset style={{ border: 0, padding: 0, margin: 0 }} className="stack stack--tight">
      <legend style={{ fontSize: 13, fontWeight: 700, padding: 0 }}>{legend}</legend>
      <div className="row" style={{ flexWrap: 'wrap', gap: 'var(--space-2)' }}>
        {options.map((option) => (
          <button
            key={option}
            type="button"
            className="btn btn--sm btn--soft"
            aria-pressed={value === option}
            onClick={() => onChange(option)}
          >
            {label(option)}
          </button>
        ))}
      </div>
    </fieldset>
  )
}

/** One of the three lists: header, optional add button, live rows, price floor. */
function WishSection({
  title,
  hint,
  wishes,
  emptyTitle,
  emptyHint,
  banner,
  onAdd,
  renderRow,
}: {
  title: string
  hint: string
  wishes: Wish[]
  emptyTitle: string
  emptyHint: string
  banner?: string
  onAdd?: () => void
  renderRow: (w: Wish) => React.ReactNode
}) {
  const { t, locale } = useI18n()
  const open = wishes.filter((w) => !w.fulfilledAt)
  const done = wishes.filter((w) => w.fulfilledAt)
  const price = priceSummary(open)

  return (
    <Card
      title={title}
      icon="memories"
      hint={hint}
      action={
        onAdd && (
          <button className="btn btn--sm" onClick={onAdd}>
            <Icon name="plus" size={16} /> {t('wishlist.add')}
          </button>
        )
      }
    >
      {banner && open.length > 0 && <p className="banner">{banner}</p>}

      {open.length === 0 && done.length === 0 ? (
        <EmptyState icon="memories" title={emptyTitle} hint={emptyHint} />
      ) : (
        <ul className="list">{open.map(renderRow)}</ul>
      )}

      {price.priced > 0 && (
        <p className="disclaimer">
          {price.complete
            ? t('wishlist.priceAll', { total: formatRupiah(price.total, locale) })
            : t('wishlist.pricePartial', {
                total: formatRupiah(price.total, locale),
                priced: price.priced,
                count: price.count,
              })}{' '}
          {t('wishlist.priceCaveat')}
        </p>
      )}

      {done.length > 0 && (
        <details style={{ marginTop: 'var(--space-2)' }}>
          <summary style={{ cursor: 'pointer', fontSize: 13, fontWeight: 700 }}>
            {t('wishlist.archived', { n: done.length })}
          </summary>
          <ul className="list" style={{ marginTop: 'var(--space-2)' }}>
            {done.map(renderRow)}
          </ul>
        </details>
      )}
    </Card>
  )
}

/** Title, urgency, price and link — the part that looks the same to everyone. */
function WishBody({ wish }: { wish: Wish }) {
  const { t, locale } = useI18n()
  const href = safeLink(wish.link)
  return (
    <span className="grow stack stack--tight">
      <strong style={{ fontSize: 14 }}>{wish.title}</strong>
      <span className="row" style={{ flexWrap: 'wrap', gap: 6 }}>
        <span className={URGENCY_CHIP[wish.urgency]}>{t(`wishlist.u.${wish.urgency}` as const)}</span>
        {wish.fulfilledAt && (
          <span className="chip chip--mint">
            <Icon name="check" size={14} />
            {t('wishlist.doneChip')}
          </span>
        )}
        {typeof wish.priceEstimate === 'number' && (
          <span className="card__hint">{formatRupiah(wish.priceEstimate, locale)}</span>
        )}
      </span>
      {wish.note && <span className="card__hint">{wish.note}</span>}
      {href && (
        <a href={href} target="_blank" rel="noreferrer noopener" style={{ fontSize: 13 }}>
          {t('wishlist.openLink', { title: wish.title })}
        </a>
      )}
    </span>
  )
}

/** My own wish, or a joint one: edit, archive, delete. No gift state here. */
function OwnerRow({
  wish,
  me,
  onEdit,
  showVisibility,
}: {
  wish: Wish
  me: string
  onEdit: () => void
  showVisibility?: boolean
}) {
  const { t } = useI18n()
  return (
    <li className="list__item" style={{ flexWrap: 'wrap' }}>
      <WishBody wish={wish} />
      {showVisibility && <VisibilityBadge visibility={wish.visibility} />}
      <button
        className="btn btn--ghost btn--sm"
        onClick={() =>
          patch(WISHES, wish.id, {
            fulfilledAt: wish.fulfilledAt ? undefined : new Date().toISOString(),
          })
        }
      >
        {wish.fulfilledAt ? t('wishlist.undoDone') : t('wishlist.markDone')}
      </button>
      <button className="btn btn--ghost btn--sm btn--icon" onClick={onEdit}>
        <Icon name="settings" size={16} label={t('wishlist.editTitle')} />
      </button>
      <button
        className="btn btn--ghost btn--sm btn--icon"
        onClick={() => softDelete(WISHES, wish.id, me)}
      >
        <Icon name="close" size={16} label={t('common.deleteX', { name: wish.title })} />
      </button>
    </li>
  )
}

/**
 * The partner's wish, seen by the possible giver. Reserving writes a private
 * record of mine rather than touching their wish — the owner's row never
 * changes, so nothing on their screen can hint at what is coming.
 */
function GiverRow({
  wish,
  me,
  reservation,
  onReserve,
}: {
  wish: Wish
  me: string
  reservation: Reservation | undefined
  onReserve: () => void
}) {
  const { t, locale } = useI18n()
  const given = reservation?.status === 'sudah_dikasih'
  return (
    <li className="list__item" style={{ flexWrap: 'wrap' }}>
      <WishBody wish={wish} />
      {reservation ? (
        <>
          <span className="chip chip--lavender">
            <Icon name="private" size={14} />
            {t('wishlist.secretChip')}
          </span>
          <span className="card__hint">
            {given ? t('wishlist.given') : t('wishlist.reserved')} ·{' '}
            {whenLabel(reservation.createdAt, t, locale)}
          </span>
          <button
            className="btn btn--ghost btn--sm"
            onClick={() =>
              patch(WISHES, reservation.id, { status: given ? 'diambil' : 'sudah_dikasih' })
            }
          >
            {given ? t('wishlist.undoGiven') : t('wishlist.markGiven')}
          </button>
          <button
            className="btn btn--ghost btn--sm"
            onClick={() => softDelete(WISHES, reservation.id, me)}
          >
            {t('wishlist.cancelReserve')}
          </button>
        </>
      ) : (
        <button className="btn btn--sm btn--soft" onClick={onReserve}>
          <Icon name="heart" size={16} /> {t('wishlist.reserve')}
        </button>
      )}
    </li>
  )
}
