import type { Reservation, Urgency, Wish, WishRecord } from '@/types/domain'

/**
 * Wishlist model + pure logic.
 *
 * The record types live in `types/domain.ts` with everything else; the reason
 * they are shaped the way they are is worth repeating here, because it is the
 * whole design: a *reservation* is a separate record owned by the person who
 * reserved, left at the C3 default visibility (`private`). It is therefore
 * unreadable by the wish's owner through `canRead()` — the surprise is
 * protected by the same gate that protects everything else, not by hiding a
 * field in the UI. Putting `reservedBy` on the wish itself would have leaked it
 * into the owner's own row, their backup, and their export.
 */

export const WISHES = 'wishes' as const

export type { Reservation, Urgency, Wish, WishRecord, WishScope } from '@/types/domain'

export const URGENCIES: readonly Urgency[] = ['lagi_butuh', 'lagi_pengin', 'kapan_kapan']

export const isWish = (r: WishRecord): r is Wish => r.kind === 'wish'
export const isReservation = (r: WishRecord): r is Reservation => r.kind === 'reservation'

/** "Lagi butuh" first — that is the only ordering anyone asked for. */
const RANK: Record<Urgency, number> = { lagi_butuh: 0, lagi_pengin: 1, kapan_kapan: 2 }

export function sortWishes(list: Wish[]): Wish[] {
  return [...list].sort(
    (a, b) => RANK[a.urgency] - RANK[b.urgency] || b.createdAt.localeCompare(a.createdAt),
  )
}

export interface WishLists {
  mine: Wish[]
  partner: Wish[]
  together: Wish[]
}

/**
 * Splits whatever the read gate handed us into the three on-screen lists.
 * Anything not owned by me and not joint is, by definition, the other person's —
 * we never ask for a partner id, so this still works before pairing.
 */
export function groupWishes(rows: WishRecord[], meId: string): WishLists {
  const wishes = rows.filter(isWish)
  return {
    mine: sortWishes(wishes.filter((w) => w.scope === 'sendiri' && w.ownerProfileId === meId)),
    partner: sortWishes(wishes.filter((w) => w.scope === 'sendiri' && w.ownerProfileId !== meId)),
    together: sortWishes(wishes.filter((w) => w.scope === 'bareng')),
  }
}

export function reservationOf(reservations: Reservation[], wishId: string): Reservation | undefined {
  return reservations.find((r) => r.wishId === wishId)
}

export interface PriceSummary {
  /** Sum of the estimates that exist. A floor, never a forecast. */
  total: number
  priced: number
  count: number
  /** True when every item carries an estimate, so `total` is not an undercount. */
  complete: boolean
}

/**
 * No ± band is invented here. Items without an estimate are simply counted, and
 * the UI says "minimal X dari N barang" — an honest lower bound beats a
 * confident-looking range built from a made-up percentage.
 */
export function priceSummary(list: Wish[]): PriceSummary {
  const priced = list.filter((w) => typeof w.priceEstimate === 'number' && w.priceEstimate > 0)
  return {
    total: priced.reduce((sum, w) => sum + (w.priceEstimate ?? 0), 0),
    priced: priced.length,
    count: list.length,
    complete: list.length > 0 && priced.length === list.length,
  }
}

/** "250.000", "Rp 250rb-ish" → 250000. Anything with no digits → undefined. */
export function parsePrice(input: string): number | undefined {
  const digits = input.replace(/\D/g, '')
  if (!digits) return undefined
  const n = Number(digits)
  return Number.isFinite(n) && n > 0 ? n : undefined
}

/**
 * Trust boundary: this string came from a keyboard and later becomes an `href`.
 * A stored `javascript:` or `data:` URL would execute inside the app's own
 * origin, next to the whole database, so only http(s) is ever allowed out.
 */
export function safeLink(raw: string | undefined): string | undefined {
  if (!raw) return undefined
  try {
    const url = new URL(raw)
    return url.protocol === 'http:' || url.protocol === 'https:' ? url.href : undefined
  } catch {
    return undefined
  }
}

/** People paste "tokopedia.com/x" without a scheme; assume https rather than reject. */
export function normalizeLink(input: string): string | undefined {
  const raw = input.trim()
  if (!raw) return undefined
  return safeLink(raw) ?? safeLink(`https://${raw}`)
}
